import type * as runtime from "@cloudflare/workers-types";
import * as Binding from "alchemy/Binding";
import type { RuntimeContext } from "alchemy/RuntimeContext";
import * as Data from "effect/Data";
import * as Effect from "effect/Effect";
import type { SendEmail } from "./SendEmail.ts";

/**
 * Bind a {@link SendEmail} `send_email` descriptor to a Worker and obtain the
 * Effect-native client for sending email.
 *
 * `Send` is a single identifier that is simultaneously the binding's Context
 * tag, its type, and the callable — `yield* Cloudflare.Email.Send(EmailDescriptor)`.
 *
 * **Example:** Send to any verified destination
 * ```typescript
 * const Email = Cloudflare.Email.SendEmail("Email");
 *
 * // in the Worker effect:
 * const email = yield* Cloudflare.Email.Send(Email);
 * yield* email.send({
 *   from: "noreply@example.com",
 *   to: "user@example.com",
 *   subject: "Hello",
 *   text: "Hi from Alchemy",
 * });
 * ```
 *
 * @binding
 * @product Email
 * @category Email
 */
export interface Send extends Binding.Service<
  Send,
  "Cloudflare.Email.SendEmail",
  (sender: SendEmail) => Effect.Effect<SendClient>
> {}

export const Send = Binding.Service<Send>("Cloudflare.Email.SendEmail");

/**
 * Email body shape for the builder-form `send` call. Either `text`, `html`,
 * or both must be provided.
 */
export interface SendEmailMessage {
  from: string | runtime.EmailAddress;
  to: string | string[];
  subject: string;
  replyTo?: string | runtime.EmailAddress;
  cc?: string | string[];
  bcc?: string | string[];
  headers?: Record<string, string>;
  text?: string;
  html?: string;
  attachments?: runtime.EmailAttachment[];
}

export class SendEmailError extends Data.TaggedError("SendEmailError")<{
  message: string;
  cause?: unknown;
}> {}

export interface SendClient {
  /**
   * The raw runtime `SendEmail` binding. Use this when you need direct
   * access to the Cloudflare object (e.g. to send a pre-built
   * `EmailMessage` from `cloudflare:email`).
   */
  raw: Effect.Effect<runtime.SendEmail, never, RuntimeContext>;
  /**
   * Send an email using the builder form. Equivalent to calling
   * `env.<name>.send({ from, to, subject, text, html, ... })`.
   */
  send(
    message: SendEmailMessage,
  ): Effect.Effect<runtime.EmailSendResult, SendEmailError, RuntimeContext>;
  /**
   * Send a raw `EmailMessage` (constructed via `cloudflare:email`).
   */
  sendRaw(
    message: runtime.EmailMessage,
  ): Effect.Effect<runtime.EmailSendResult, SendEmailError, RuntimeContext>;
}
import type * as runtime from "@cloudflare/workers-types";
import * as Effect from "effect/Effect";
import * as Layer from "effect/Layer";
import { Worker, WorkerEnvironment } from "../Workers/Worker.ts";
import { Send, SendEmailError, type SendClient, type SendEmailMessage } from "./Send.ts";
import type { SendEmail } from "./SendEmail.ts";

export const SendBinding = Layer.effect(
  Send,
  Effect.gen(function* () {
    const host = yield* Worker;
    const env = yield* WorkerEnvironment;

    return Effect.fn(function* (sender: SendEmail) {
      if (!globalThis.__ALCHEMY_RUNTIME__) {
        yield* host.bind(sender.name, {
          bindings: [
            {
              type: "send_email",
              name: sender.name,
              destinationAddress: sender.destinationAddress,
              allowedDestinationAddresses: sender.allowedDestinationAddresses,
              allowedSenderAddresses: sender.allowedSenderAddresses,
            },
          ],
          // Dev-only local-emulation opt-out, contributed as a parallel
          // channel (like `hyperdrives`) so the wire binding stays pure.
          ...(sender.devRemote ? { devRemote: { [sender.name]: true } } : {}),
        });
      }

      const raw = Effect.sync(() => (env as Record<string, runtime.SendEmail>)[sender.name]!);

      const tryPromise = <T>(fn: () => Promise<T>): Effect.Effect<T, SendEmailError> =>
        Effect.tryPromise({
          try: fn,
          catch: (error: any) =>
            new SendEmailError({
              message: error?.message ?? "Unknown send_email error",
              cause: error,
            }),
        });

      return {
        raw,
        send: (message: SendEmailMessage) =>
          raw.pipe(Effect.flatMap((s) => tryPromise(() => s.send(message)))),
        sendRaw: (message: runtime.EmailMessage) =>
          raw.pipe(Effect.flatMap((s) => tryPromise(() => s.send(message)))),
      } satisfies SendClient;
    });
  }),
);
import { ProviderModePolicy } from "alchemy/ProviderMode";
import * as Effect from "effect/Effect";

type SendEmailTypeId = typeof SendEmailTypeId;
const SendEmailTypeId = "Cloudflare.Email.SendEmail" as const;

export type SendEmailProps = {
  /**
   * Restrict the Worker to send to a single verified destination address.
   *
   * Mutually exclusive with `allowedDestinationAddresses`. The destination
   * must be a verified address on the account (see {@link Address}).
   */
  destinationAddress?: string;
  /**
   * Restrict the Worker to send to one of these verified destination addresses.
   *
   * Mutually exclusive with `destinationAddress`.
   */
  allowedDestinationAddresses?: string[];
  /**
   * Restrict the Worker to send from one of these sender addresses.
   *
   * The sender domain must have Email Routing configured (see
   * {@link Routing}) and the addresses must be verified.
   */
  allowedSenderAddresses?: string[];
};

/**
 * A Cloudflare Workers `send_email` binding descriptor.
 *
 * `SendEmail` is a Worker-only binding — it does not create any cloud-side
 * resource. The descriptor names the binding and records optional
 * destination/sender restrictions; the actual `send_email` entry is attached
 * to the Worker via {@link SendBinding}.
 *
 * Under `alchemy dev` the binding is lowered onto the local email simulator:
 * `send()` validates the message and persists it as a `.eml` under
 * `.alchemy/local/email` instead of delivering mail. Pipe the descriptor
 * through `Alchemy.remote()` to send through the live Cloudflare Email
 * service in dev — the same opt-out aspect resources use.
 *
 *
 * ### Binding to a Worker
 * **Example:** Send to any verified destination
 * ```typescript
 * const Email = Cloudflare.Email.SendEmail("Email");
 *
 * // in the Worker effect:
 * const email = yield* Cloudflare.Email.Send(Email);
 * yield* email.send({
 *   from: "noreply@example.com",
 *   to: "user@example.com",
 *   subject: "Hello",
 *   text: "Hi from Alchemy",
 * });
 * ```
 *
 * **Example:** Restrict the sender address
 * ```typescript
 * const Ops = Cloudflare.Email.SendEmail("OpsEmail", {
 *   allowedSenderAddresses: ["noreply@example.com"],
 *   destinationAddress: "ops@example.com",
 * });
 * ```
 *
 * ### Local development
 * **Example:** Send real mail from the dev loop
 * ```typescript
 * // Default: `send()` lands in the local simulator under `alchemy dev`.
 * // Alchemy.remote() opts into the live Email service instead:
 * const Email = Cloudflare.Email.SendEmail("Email", {
 *   allowedSenderAddresses: ["noreply@example.com"],
 * }).pipe(Alchemy.remote());
 * ```
 *
 * @resource
 */
export type SendEmail = SendEmailProps & {
  kind: SendEmailTypeId;
  name: string;
  /**
   * Alchemy-internal: opt-out of local emulation in `alchemy dev` — the
   * `Alchemy.remote()` decoration captured at registration time. Registered
   * on the host Worker via the binding-data `devRemote` channel, never on
   * the wire binding itself.
   */
  devRemote?: boolean;
};

export const isSendEmail = (value: unknown): value is SendEmail =>
  typeof value === "object" &&
  value !== null &&
  "kind" in value &&
  (value as SendEmail).kind === SendEmailTypeId;

export const SendEmail: (id: string, props?: SendEmailProps) => Effect.Effect<SendEmail> =
  Effect.fn(function* (id: string, props?: SendEmailProps) {
    // Capture the `Alchemy.remote()` decoration the same way resources do —
    // at registration time, from the ambient ProviderModePolicy reference.
    // `send_email` has no cloud-side resource (and thus no provider mode to
    // stamp), so the captured flag rides on the descriptor instead.
    const devRemote = (yield* ProviderModePolicy) === true || undefined;
    return {
      kind: SendEmailTypeId,
      name: id,
      destinationAddress: props?.destinationAddress,
      allowedDestinationAddresses: props?.allowedDestinationAddresses,
      allowedSenderAddresses: props?.allowedSenderAddresses,
      devRemote,
    } satisfies SendEmail;
  });

