    readonly recipient: string;
    readonly subject: string;
    readonly text: string;
  }>;
  readonly indexed: ReadonlyArray<{ readonly organization_id: string; readonly send_id: string }>;
}

const call = (method: "GET" | "POST", query: string) =>
